'@
[System.IO.File]::WriteAllBytes($archive, [Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne '2cefb2bb168ea8cd7ff0b891eeeeec21adf691d70fbcc85b50150f354320a355') { throw 'Pacote da central alterado. Nada foi publicado.' }
Expand-Archive -LiteralPath $archive -DestinationPath $site
Write-Host ('Pasta da central: ' + $site)
if ($NaoPublicar) { Write-Host 'Central preparada; nenhuma publicacao ou migracao executada.'; exit 0 }
Push-Location $site
try {
    & npm.cmd install
    if ($LASTEXITCODE -ne 0) { throw 'Falha ao instalar Wrangler. Nada foi publicado.' }
    & npm.cmd run check
    if ($LASTEXITCODE -ne 0) { throw 'Falha na verificacao da central. Nada foi publicado.' }
    & npx.cmd wrangler deploy --config .\wrangler.jsonc
    if ($LASTEXITCODE -ne 0) { throw ('Publicacao nao confirmada. Verifique o login Wrangler e envie a saida. Pasta: ' + $site) }
    Write-Host 'Central publicada no Worker existente. Nenhum banco/tabela foi criado.'
} finally { Pop-Location }
